"use client";
import { FormEvent, useEffect, useState } from "react";
import type { PackageItem, SiteContent } from "../../../lib/site-types";
const blank=():PackageItem=>({name:"پکیج جدید",age:"",description:"",price:"استعلام قیمت",details:"",includes:"",image:"/images/packages.jpg"});
export default function ProductsPage(){const [content,setContent]=useState<SiteContent|null>(null),[message,setMessage]=useState("");useEffect(()=>{fetch("/api/content").then(r=>r.json()).then(setContent);},[]);if(!content)return <main className="admin"><p>در حال باز کردن...</p></main>;const edit=(i:number,key:keyof PackageItem,value:string)=>setContent(o=>o&&({...o,packages:o.packages.map((p,n)=>n===i?{...p,[key]:value}:p)}));const add=()=>setContent(o=>o&&({...o,packages:[...o.packages,blank()]}));const remove=(i:number)=>setContent(o=>o&&({...o,packages:o.packages.filter((_,n)=>n!==i)}));async function upload(e:React.ChangeEvent<HTMLInputElement>,i:number){const f=e.target.files?.[0];if(!f)return;const form=new FormData();form.append("file",f);form.append("kind","packages");const r=await fetch("/api/upload",{method:"POST",body:form}),d=await r.json();if(r.ok)edit(i,"image",d.path);else setMessage(d.message||"آپلود نشد.");}async function save(e:FormEvent){e.preventDefault();const r=await fetch("/api/content",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(content)});setMessage(r.ok?"پکیج‌ها ذخیره شدند.":"ذخیره انجام نشد.");}return <main className="admin"><div className="adminHead"><div><small>پنل مدیریت</small><h1>مدیریت پکیج‌ها</h1></div><div><a href="/admin">بازگشت به پنل</a><a href="/" target="_blank">مشاهده سایت</a></div></div><form className="editor" onSubmit={save}>{content.packages.map((p,i)=><section key={i}><div className="productTitle"><h2>پکیج {i+1}</h2><button type="button" className="danger" onClick={()=>remove(i)}>حذف پکیج</button></div><label>نام<input value={p.name} onChange={e=>edit(i,"name",e.target.value)}/></label><label>بازه سنی<input value={p.age} onChange={e=>edit(i,"age",e.target.value)}/></label><label>قیمت<input value={p.price||""} onChange={e=>edit(i,"price",e.target.value)}/></label><label>توضیح کوتاه<textarea value={p.description} onChange={e=>edit(i,"description",e.target.value)}/></label><label>توضیح کامل<textarea value={p.details||""} onChange={e=>edit(i,"details",e.target.value)}/></label><label>محتویات پکیج<textarea value={p.includes||""} onChange={e=>edit(i,"includes",e.target.value)}/></label><label>تصویر اختصاصی<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>upload(e,i)}/></label>{p.image&&<img className="adminPreview" src={p.image} alt={p.name}/>}</section>)}<button type="button" className="addProduct" onClick={add}>+ افزودن پکیج جدید</button><button className="save">ذخیره همه تغییرات</button>{message&&<p className="status">{message}</p>}</form></main>}
